CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, status text NOT NULL DEFAULT 'pending_email' CHECK(status IN ('pending_email','onboarding','active','paused','suspended','deleted')), role text NOT NULL DEFAULT 'member' CHECK(role IN ('member','moderator','admin')), confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, csrf text NOT NULL, expires_at timestamptz NOT NULL, authenticated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE challenges(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users, purpose text NOT NULL, code_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profile_private(user_id uuid PRIMARY KEY REFERENCES users,birth_date date, gender text, genders text[] NOT NULL DEFAULT '{}', age_min integer NOT NULL DEFAULT 18 CHECK(age_min>=18), age_max integer NOT NULL DEFAULT 99 CHECK(age_max>=age_min));
CREATE TABLE profiles(user_id uuid PRIMARY KEY REFERENCES users, display_name varchar(50) NOT NULL DEFAULT '',bio varchar(500) NOT NULL DEFAULT '',city text NOT NULL DEFAULT 'Seattle',intention text NOT NULL DEFAULT 'Long-term relationship',interests text[] NOT NULL DEFAULT '{}',prompts jsonb NOT NULL DEFAULT '[]',photos text[] NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1);
CREATE TABLE media(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users,bytes bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE decisions(actor_id uuid REFERENCES users,target_id uuid REFERENCES users,action text NOT NULL CHECK(action IN ('like','pass')),mutation_id uuid NOT NULL,PRIMARY KEY(actor_id,target_id),UNIQUE(actor_id,mutation_id),CHECK(actor_id<>target_id));
CREATE TABLE matches(id uuid PRIMARY KEY,low_id uuid NOT NULL REFERENCES users,high_id uuid NOT NULL REFERENCES users,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','closed')),last_sequence integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(low_id,high_id),CHECK(low_id<high_id));
CREATE TABLE messages(id uuid PRIMARY KEY,match_id uuid NOT NULL REFERENCES matches,sequence integer NOT NULL,sender_id uuid NOT NULL REFERENCES users,client_id uuid NOT NULL,text varchar(2000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(sender_id,client_id),UNIQUE(match_id,sequence));
CREATE INDEX messages_match ON messages(match_id,sequence);
CREATE TABLE blocks(actor_id uuid REFERENCES users,target_id uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,target_id),CHECK(actor_id<>target_id));
CREATE TABLE reports(id uuid PRIMARY KEY,reporter_id uuid NOT NULL REFERENCES users,subject_id uuid NOT NULL REFERENCES users,category text NOT NULL,notes varchar(2000) NOT NULL DEFAULT '',state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','dismissed','reviewed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE catalogue(id text PRIMARY KEY,title text NOT NULL,activity text NOT NULL,description text NOT NULL,address text NOT NULL,price_cents integer NOT NULL CHECK(price_cents>=0),duration_minutes integer NOT NULL,accessibility text NOT NULL,policy text NOT NULL);
CREATE TABLE date_plans(id uuid PRIMARY KEY,match_id uuid NOT NULL REFERENCES matches,creator_id uuid NOT NULL REFERENCES users,status text NOT NULL DEFAULT 'collecting_preferences',financial_state text NOT NULL DEFAULT 'unpaid',version integer NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private_date_preferences(plan_id uuid NOT NULL REFERENCES date_plans,user_id uuid NOT NULL REFERENCES users,budget_encrypted text NOT NULL,activities text[] NOT NULL,time_start timestamptz NOT NULL,time_end timestamptz NOT NULL,PRIMARY KEY(plan_id,user_id),CHECK(time_end>time_start));
CREATE TABLE proposals(plan_id uuid REFERENCES date_plans,version integer NOT NULL,catalogue_id text NOT NULL REFERENCES catalogue,starts_at timestamptz NOT NULL,timezone text NOT NULL DEFAULT 'America/Los_Angeles',snapshot jsonb NOT NULL,PRIMARY KEY(plan_id,version));
CREATE TABLE acceptances(plan_id uuid REFERENCES date_plans,version integer NOT NULL,user_id uuid REFERENCES users,PRIMARY KEY(plan_id,version,user_id),FOREIGN KEY(plan_id,version) REFERENCES proposals(plan_id,version));
CREATE TABLE purchases(id uuid PRIMARY KEY,plan_id uuid NOT NULL REFERENCES date_plans,version integer NOT NULL,buyer_id uuid NOT NULL REFERENCES users,amount_cents integer NOT NULL CHECK(amount_cents>0),currency text NOT NULL DEFAULT 'USD' CHECK(currency='USD'),snapshot jsonb NOT NULL,state text NOT NULL DEFAULT 'created',UNIQUE(plan_id,version,buyer_id));
CREATE TABLE payments(id uuid PRIMARY KEY,purchase_id uuid UNIQUE NOT NULL REFERENCES purchases,mode text NOT NULL,state text NOT NULL DEFAULT 'created',order_id text UNIQUE,capture_id text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_operations(id uuid PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments,kind text NOT NULL,state text NOT NULL DEFAULT 'pending',result jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(payment_id,kind));
CREATE TABLE refunds(id uuid PRIMARY KEY,payment_id uuid UNIQUE NOT NULL REFERENCES payments,amount_cents integer NOT NULL CHECK(amount_cents>0),provider_id text UNIQUE,state text NOT NULL DEFAULT 'requested');
CREATE TABLE financial_events(id uuid PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments,type text NOT NULL,source_id text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_inbox(event_id text PRIMARY KEY,mode text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id uuid PRIMARY KEY,kind text NOT NULL,aggregate_id uuid NOT NULL,payload jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,aggregate_id));
CREATE TABLE notifications(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,event_id uuid NOT NULL,category text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_id));
CREATE TABLE audit_log(id uuid PRIMARY KEY,actor_id uuid REFERENCES users,action text NOT NULL,resource_id uuid,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX date_plan_match ON date_plans(match_id,status);
CREATE INDEX payment_state ON payments(state,updated_at);
CREATE INDEX outbox_pending ON outbox(state,available_at);
